# PTX source for fp16 GEMM (A[M,K] * B[K,N] = C[M,N])
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

// Kernel: gemm_fp16
// Parameters:
//   .param .u64 A_ptr
//   .param .u64 B_ptr
//   .param .u64 C_ptr
//   .param .u32 M
//   .param .u32 N
//   .param .u32 K
.visible .entry gemm_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // ------------------------------
    // Register declarations
    // ------------------------------
    .reg .pred   %p_done;
    .reg .pred   %p_bound;
    .reg .u32    %tid_x, %tid_y;
    .reg .u32    %bid_x, %bid_y;
    .reg .u32    %row, %col;
    .reg .u32    %tmp;
    .reg .u64    %A, %B, %C;
    .reg .u64    %addrA, %addrB, %addrC;
    .reg .u16    %a_half, %b_half;
    .reg .f32    %a_f32, %b_f32;
    .reg .f32    %sum;
    .reg .u32    %k_idx;
    .reg .u32    %M, %N, %K;

    // ------------------------------
    // Load kernel parameters
    // ------------------------------
    ld.param.u64    %A, [A_ptr];
    ld.param.u64    %B, [B_ptr];
    ld.param.u64    %C, [C_ptr];
    ld.param.u32    %M, [M];
    ld.param.u32    %N, [N];
    ld.param.u32    %K, [K];

    // ------------------------------
    // Thread/block indices
    // ------------------------------
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    // Compute global row and column this thread will write
    mad.lo.u32 %row, %bid_y, 16, %tid_y;   // row = blockY*16 + threadY
    mad.lo.u32 %col, %bid_x, 16, %tid_x;   // col = blockX*16 + threadX

    // Bounds check: if (row >= M || col >= N) exit
    setp.ge.u32 %p_bound, %row, %M;
    @%p_bound bra DONE;
    setp.ge.u32 %p_bound, %col, %N;
    @%p_bound bra DONE;

    // Initialize accumulator
    mov.f32 %sum, 0f00000000;

    // Loop over K dimension
    mov.u32 %k_idx, 0;
LOOP_K:
    setp.ge.u32 %p_done, %k_idx, %K;
    @%p_done bra END_LOOP;

    // Compute address of A[row, k_idx]
    // offset = (row * K + k_idx) * 2 (size of half)
    mul.wide.u32 %addrA, %row, %K;          // row*K
    mad.lo.u32    %tmp, %addrA, 1, %k_idx; // (row*K) + k_idx
    mul.wide.u32 %addrA, %tmp, 2;          // *2 bytes

    // Load half from A
    ld.global.b16 %a_half, [%A + %addrA];

    // Compute address of B[k_idx, col]
    // offset = (k_idx * N + col) * 2
    mul.wide.u32 %addrB, %k_idx, %N;       // k_idx * N
    mad.lo.u32    %tmp, %addrB, 1, %col;   // (k_idx*N) + col
    mul.wide.u32 %addrB, %tmp, 2;          // *2 bytes

    // Load half from B
    ld.global.b16 %b_half, [%B + %addrB];

    // Convert to fp32
    cvt.f32.f16 %a_f32, %a_half;
    cvt.f32.f16 %b_f32, %b_half;

    // Accumulate
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // k_idx++
    add.u32 %k_idx, %k_idx, 1;
    bra LOOP_K;

END_LOOP:
    // Convert sum back to half (round to nearest)
    cvt.rn.f16.f32 %a_half, %sum;   // reuse %a_half as output half

    // Compute address of C[row, col]
    // offset = (row * N + col) * 2
    mul.wide.u32 %addrC, %row, %N;        // row*N
    mad.lo.u32    %tmp, %addrC, 1, %col; // (row*N) + col
    mul.wide.u32 %addrC, %tmp, 2;        // *2 bytes

    // Store result
    st.global.b16 [%C + %addrC], %a_half;

DONE:
    ret;
}
'''

