    def __init__(self):
        # Load the PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A, B):
        """
        A: torch.Tensor of shape (M, K), dtype=torch.float16, device='cuda'
        B: torch.Tensor of shape (K, N), dtype=torch.float16, device='cuda'
        Returns:
            C: torch.Tensor of shape (M, N), dtype=torch.float16, device='cuda'
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        K2, N = B.shape
        assert K == K2

        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # Launch configuration: 16x16 threads per block
        block_dim = (16, 16, 1)
        grid_dim = ((N + 15) // 16, (M + 15) // 16, 1)

        # Arguments: pointers and dimensions
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            N,
            K
        ]

        # Launch the kernel
        ptx_launch(self.module, "gemm_fp16", grid_dim, block_dim, args)

        return C
